verus! {
    /// Compute the canonical decomposition count.
    /// 
    /// # Parameters
    /// - `n`: a positive `i8` amount (n >= 1)
    ///
    /// # Returns
    /// - `result`: an `i8` equal to 
    ///     n/100
    ///   + (n%100)/20
    ///   + ((n%100)%20)/10
    ///   + (((n%100)%20)%10)/5
    ///   + (((n%100)%20)%10)%5,
    ///   which is the minimum number of notes/coins needed.
    fn solve(n: i8) -> (result: i8)
        requires n >= 1
        ensures result >= 0
        ensures result ==
            n / 100
          + (n % 100) / 20
          + ((n % 100) % 20) / 10
          + (((n % 100) % 20) % 10) / 5
          + (((n % 100) % 20) % 10) % 5
    {
        // number of 100-unit notes
        let c100: i8 = n / 100;
        let rem100: i8 = n % 100;
        // number of 20-unit notes
        let c20: i8 = rem100 / 20;
        let rem20: i8 = rem100 % 20;
        // number of 10-unit notes
        let c10: i8 = rem20 / 10;
        let rem10: i8 = rem20 % 10;
        // number of 5-unit coins
        let c5: i8 = rem10 / 5;
        let rem5: i8 = rem10 % 5;
        // the remaining 1-unit coins
        let c1: i8 = rem5;
        
        // sum them up
        let sum: i8 = c100 + c20 + c10 + c5 + c1;
        
        // all partial counts are non-negative because n >= 1
        assert(c100 >= 0);
        assert(rem100 >= 0);
        assert(c20 >= 0);
        assert(rem20 >= 0);
        assert(c10 >= 0);
        assert(rem10 >= 0);
        assert(c5 >= 0);
        assert(rem5 >= 0);
        assert(c1 >= 0);
        assert(sum >= 0);
        
        sum
    }
}

